import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { redirect } from "next/navigation";
import { getAdminRequestSheet, getAdminWorkflowMatrix } from "@/lib/queries";
import { AdminRequestSheet } from "@/components/admin-request-sheet";
import { AdminWorkflowTable } from "@/components/admin-workflow-table";

export default async function DataPage() {
  const user = await requireUser();
  if (!checkPermission(user.role, "admin.data", "view")) {
    redirect("/dashboard");
  }

  const requestSheetRows = getAdminRequestSheet();
  const { columns: workflowColumns, rows: workflowRows } = getAdminWorkflowMatrix();

  return (
    <div>
      <div style={{ marginBottom: 20 }}>
        <h2 style={{ fontSize: 18, fontWeight: 600, color: "#111", margin: 0 }}>데이터 관리</h2>
        <p style={{ fontSize: 12, color: "#888", margin: "2px 0 0" }}>
          채용요청 데이터와 워크플로우를 통합 관리합니다
        </p>
      </div>

      {/* 채용요청 + 워크플로우 단일 뷰 */}
      <section style={{ marginBottom: 32 }}>
        <h3 style={{ fontSize: 15, fontWeight: 600, color: "#111", marginBottom: 12 }}>
          채용요청 데이터
        </h3>
        <AdminRequestSheet initialRows={requestSheetRows} />
      </section>

      <section>
        <h3 style={{ fontSize: 15, fontWeight: 600, color: "#111", marginBottom: 12 }}>
          워크플로우 진행현황
        </h3>
        <AdminWorkflowTable columns={workflowColumns} initialRows={workflowRows} />
      </section>
    </div>
  );
}
